// Run with: node scripts/embed-apps-script.mjs          (rewrites the APPS_SCRIPT line in index.html from apps-script.gs)
//       or: node scripts/embed-apps-script.mjs --check   (changes nothing; exits 1 if index.html is out of date)
// The copy-and-paste script inside index.html must always be generated by this file, never edited by hand.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const gsPath = path.join(root, 'apps-script.gs');
const htmlPath = path.join(root, 'index.html');
const checkOnly = process.argv.includes('--check');
const fail = msg => { process.stderr.write('Error: ' + msg + '\n'); process.exit(1); };

const gs = fs.readFileSync(gsPath, 'utf8');
const html = fs.readFileSync(htmlPath, 'utf8');

// A "</script" inside the string would end the page's inline <script> early, so refuse before writing anything.
if (/<\/script/i.test(gs)) fail('apps-script.gs contains "</script", which would break the inline script tag in index.html.');

const lines = html.split('\n');
const hits = lines.map((line, i) => (line.startsWith('const APPS_SCRIPT="') ? i : -1)).filter(i => i >= 0);
if (hits.length !== 1) fail('expected exactly one line starting with const APPS_SCRIPT=" in index.html, found ' + hits.length + '.');

const next = 'const APPS_SCRIPT=' + JSON.stringify(gs) + ';';
const same = lines[hits[0]] === next;

if (checkOnly) {
  console.log(same ? 'APPS_SCRIPT is up to date' : 'APPS_SCRIPT is out of date');
  process.exit(same ? 0 : 1);
}
if (same) { console.log('APPS_SCRIPT already up to date'); process.exit(0); }

lines[hits[0]] = next;                         // only this one line changes; every other line and line ending is untouched
fs.writeFileSync(htmlPath, lines.join('\n'), 'utf8');
console.log('APPS_SCRIPT regenerated from apps-script.gs');
